217	// 相同的合法 \uXXXX 转义，原有的产物哈希与成功报告标识必须仍然有效，
218	// 状态、归属与证据完全一致。
219	func TestCLIVaultExampleJSONWriteVariantsKeepBindings(t *testing.T) {
220		original := vaultExampleInput(t)
221	
222		// 变体 1：压缩空白（缩进/换行变化），内容不变。
223		var compact bytes.Buffer
224		if err := json.Compact(&compact, original); err != nil {
225			t.Fatalf("json.Compact failed: %v", err)
226		}
227		compactVariant := compact.Bytes()
