240		// 转义——字节码里的 '6'（U+0036）、缺陷 note 里的 '攻'（U+653B）以及
241		// source 里的 'S'（U+0053，证明 source 转义也按解码后的内容参与哈希）。
242		// 解码后内容完全不变，因此公开哈希与报告标识必须保持不变。
243		escaped := bytes.Replace(reordered, []byte("0x6080604052"), []byte("0x\\u0036080604052"), 1)
244		if bytes.Contains(escaped, []byte("0x6080604052")) {
