// bytesReplaceOnce 替换第一处出现的 old（测试夹具构造用）。
func bytesReplaceOnce(s, old, neu []byte) []byte {
	idx := indexBytes(s, old)
	if idx < 0 {
		return s
	}
	out := make([]byte, 0, len(s)+len(neu)-len(old))
	out = append(out, s[:idx]...)
	out = append(out, neu...)
	out = append(out, s[idx+len(old):]...)
	return out
}

func indexBytes(s, sep []byte) int {
	for i := 0; i+len(sep) <= len(s); i++ {
		if string(s[i:i+len(sep)]) == string(sep) {
			return i
		}
	}
	return -1
}

